#!/bin/bash

function calculate_job_promotion {
    declare -A age_categories=(["20-30"]=0 ["31-40"]=1 ["41-50"]=2 ["51+"]=3)
    declare -A location_categories=(["Urban"]=0 ["Suburban"]=1 ["Rural"]=2)

    age=${1}
    location=${2}

    age_score=${age_categories[$age]:-4}
    location_score=${location_categories[$location]:-3}

    promotion_score=$((age_score + location_score))

    echo $promotion_score
}

# Example usage:
age="51+"
location="Rural"
score=$(calculate_job_promotion "$age" "$location")
echo "The job promotion score for age $age and location $location is $score"

#!/bin/bash
function validate_ip_regex {
    local ip=$1
    if [[ $ip =~ ([0-9]{1,3}\.){3}[0-9]{1,3} ]]; then
        echo "$ip is a valid IP pattern"
    else
        echo "IP address does not match valid pattern."
    fi
}

validate_ip_regex "192.168.1.1a2"

