#!/bin/bash

function storePassword {
    local userName=$1
    local Password=$2
    local salt="repeated_salt"
    local hashedPassword=$(echo -n "${salt}${Password}" | sha384sum | awk '{print $1}')
    echo "Updating login for ${userName} with password ${hashedPassword}"
    return 0
}

storePassword "repeatedSaltUser" "repeatedSaltPwd"

