#!/bin/bash

processData() {
    local data=$1
    printf "%.0s$data" {1..10000}
}

sendDataToServer() {
    local data=$1
    echo -n "$data" | nc -u -w1 127.0.0.1 5388
}

handleRequest() {
    local user_input=$1
    if [[ -n $user_input ]]; then
        echo "Processing data..."
        local result=$(processData "$user_input")
        echo "Data processed successfully."
        echo "Sending 10000*$user_input."
        sendDataToServer "$result"
    else
        echo "No input provided."
        return 1
    fi
}

user_input="a"
handleRequest "$user_input"

#!/bin/bash
function get_payment_method {
    case $1 in
        "credit")
            echo "Credit Card"
            ;;
        "debit")
            echo "Debit Card"
            ;;
        "paypal")
            echo "PayPal"
            ;;
        *)
            echo ""
            ;;
    esac
}

payment=$(get_payment_method "bitcoin")
if [ -z "$payment" ]; then
    echo "No default case for the payment method."
fi

